//! End-to-end checks for unlock, using encrypted fixtures generated by
//! tests/fixtures/make_fixtures.py (two text pages plus a bookmark).

mod common;

use std::path::Path;

use common::{engine, fixture, red_blue_pdf, TempDir};
use flatten_core::{inspect_security, unlock, Engine, FlattenError, Security, UnlockOptions};

const USER_PASSWORD_FILE: &str = "user-password-rc4.pdf";
const OWNER_RESTRICTED_FILE: &str = "owner-restricted-aes256.pdf";

/// Checks that `path` is an unprotected copy of the fixture content.
fn assert_unlocked_copy(engine: &Engine, path: &Path) {
    assert_eq!(inspect_security(engine, path).unwrap(), Security::None);
    let doc = engine.pdfium().load_pdf_from_file(path, None).unwrap();
    assert_eq!(doc.pages().len(), 2);
    let text = doc.pages().get(0).unwrap().text().unwrap().all();
    assert!(
        text.contains("Hello FlattenPDF 1"),
        "text kept, got {text:?}"
    );
    let bookmark = doc.bookmarks().root().expect("bookmark kept");
    assert_eq!(bookmark.title().as_deref(), Some("Second page"));
}

#[test]
fn reports_how_files_are_protected() {
    let Some(engine) = engine() else { return };
    let dir = TempDir::new("security");
    let plain = dir.join("plain.pdf");
    std::fs::write(&plain, red_blue_pdf("/MediaBox [0 0 100 100]")).unwrap();

    assert_eq!(inspect_security(engine, &plain).unwrap(), Security::None);
    assert_eq!(
        inspect_security(engine, &fixture(OWNER_RESTRICTED_FILE)).unwrap(),
        Security::OwnerRestricted
    );
    assert_eq!(
        inspect_security(engine, &fixture(USER_PASSWORD_FILE)).unwrap(),
        Security::PasswordRequired
    );
}

#[test]
fn removes_owner_restrictions_without_a_password() {
    let Some(engine) = engine() else { return };
    let dir = TempDir::new("owner");
    let output = dir.join("unlocked.pdf");

    let summary = unlock(
        engine,
        &fixture(OWNER_RESTRICTED_FILE),
        &output,
        &UnlockOptions::default(),
    )
    .unwrap();
    assert_eq!(summary.pages, 2);
    assert_unlocked_copy(engine, &output);
}

#[test]
fn removes_open_password_when_it_is_given() {
    let Some(engine) = engine() else { return };
    let dir = TempDir::new("user");
    let output = dir.join("unlocked.pdf");
    let input = fixture(USER_PASSWORD_FILE);

    for password in [None, Some("wrong".to_string())] {
        let err = unlock(engine, &input, &output, &UnlockOptions { password }).unwrap_err();
        assert!(matches!(err, FlattenError::PasswordRequired), "got {err:?}");
        assert!(!output.exists());
    }

    let opts = UnlockOptions {
        password: Some("secret".into()),
    };
    unlock(engine, &input, &output, &opts).unwrap();
    assert_unlocked_copy(engine, &output);
    assert!(!dir.join("unlocked.pdf.part").exists());
}
